"use strict";(globalThis.webpackChunkgrc||=[]).push([[687],{59399(e){e.exports=JSON.parse('{"citeKey":"wu2004memoryconscious","slug":"wu-2004-memory-conscious-3c6b","title":"Memory Conscious Task Partition and Scheduling in Grid Environments","authors":["M. Wu","X.-H. Sun"],"venue":"The 5th IEEE/ACM International Workshop on Grid Computing (in conjunction with SC 2004), pp. 138-145, Pittsburgh","type":"Workshop","entryType":"inproceedings","date":"November, 2004","year":2004,"era":"iit","month":11,"doi":"10.1109/grid.2004.43","abstract":"While resource management and task scheduling are identified challenges of Grid computing, current Grid scheduling systems mainly focus on CPU and network availability. Recent performance improvement of CPU and computer network has made memory usage a significant factor of overall performance. In this study, we consider memory availability as a performance factor and introduce memory conscious task partition and scheduling. Three task partition policies are discussed. They are CPU-based, memory-based, and CPU-memory combined partition. We first investigate the three task partition policies on dedicated resources and verify the effectiveness of the CPU-memory combined partition algorithm in finding an optimal solution. We then extend the task partition policies in non-dedicated environments with the consideration of resource sharing. Analytical and experimental results show that the CPU-memory combined scheduling approach outperforms either the CPU-based or memory-based scheduling approach considerably for memory-intensive applications in Grid environments.","hasAbstract":true,"lede":"While resource management and task scheduling are identified challenges of Grid computing, current Grid scheduling systems mainly focus on CPU and network availability.","links":{"pdf":"https://grc.iit.edu/papers/2004/wu-2004-memory-conscious-3c6b.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":["ghs"],"memberAuthors":["sun-xian-he"]}')}}]);